function validateSave(v){const s=v?.state;if(v?.version!==1||!s||!Array.isArray(s.party)||s.party.length<1||s.party.length>6||!Number.isInteger(s.region)||s.region<0||s.region>=D.regions.length)throw Error('This is not a valid Echoes save.');for(const a of ['party','storage']){if(!Array.isArray(s[a])||s[a].length>600)throw Error('Invalid team data.');for(const m of s[a]){if(!SPEC[m.species]||!Number.isInteger(m.level)||m.level<1||m.level>100||!Number.isFinite(m.hp)||!Array.isArray(m.moves)||m.moves.length>4||m.moves.some(mv=>!D.moves[mv.id]||!Number.isFinite(mv.pp)))throw Error('Invalid Pokémon data.');m.hp=Math.max(0,Math.min(maxhp(m),m.hp));m.xp=Math.max(0,Number(m.xp)||0);m.uid ||=Math.random().toString(36).slice(2);}}for(const a of ['defeated','badges','visited','quests','seen','caught','storyFlags'])if(!Array.isArray(s[a]))throw Error('Invalid journey data.');if(!s.items||!['ball','potion','superPotion','antidote'].every(k=>Number.isFinite(s.items[k])&&s.items[k]>=0)||!Number.isFinite(s.money)||s.money<0)throw Error('Invalid inventory.');s.x=Math.max(1,Math.min(26,Math.floor(Number(s.x))||4));s.y=Math.max(1,Math.min(18,Math.floor(Number(s.y))||10));s.active=Math.max(0,Math.min(s.party.length-1,s.active|0));s.playSeconds=Math.max(0,Number(s.playSeconds)||0);if(s.battle){if(!Array.isArray(s.battle.enemies)||!s.battle.enemies.length||s.battle.enemies.length>6||!Number.isInteger(s.battle.index)||s.battle.index<0||s.battle.index>=s.battle.enemies.length||s.battle.enemies.some(m=>!SPEC[m.species]||!Number.isInteger(m.level)||m.level<1||m.level>100||!Number.isFinite(m.hp)||m.hp<0||m.hp>maxhp(m)||!Array.isArray(m.moves)||m.moves.length>4||m.moves.some(mv=>!D.moves[mv.id]||!Number.isFinite(mv.pp)||mv.pp<0||mv.pp>D.moves[mv.id].pp)))throw Error('Invalid battle.');if(s.battle.trainerId&&!D.regions.some(r=>r.trainers.some(t=>t.id===s.battle.trainerId)))throw Error('Unknown trainer.');}return s;}
